        };
        let mut second = base.clone();
        second.id = "b".into();
        let results = search_island("same", &[second, base]);
        let ids: Vec<_> = results
            .iter()
            .map(|result| match result {
                IslandResult::Session(item) => item.id.as_str(),
            })
            .collect();
        assert_eq!(ids, vec!["b", "a"]);
    }
}

